"""Read-only guard for SQL generated by Node 2 Text-to-SQL.

The guard is the first defence layer; the runner also opens SQLite in
read-only mode with ``PRAGMA query_only=ON``. Checks run on a masked copy of
the statement in which string literals and comments are blanked, so keywords
inside literals (``LIKE '%DROP%'``) do not trigger false rejections.
"""

from __future__ import annotations

import re

ALLOWED_VIEWS: tuple[str, ...] = ("v_invoice_facts", "v_item_facts", "v_tax_facts")

FORBIDDEN_KEYWORDS: tuple[str, ...] = (
    "INSERT",
    "UPDATE",
    "DELETE",
    "DROP",
    "ALTER",
    "CREATE",
    "REPLACE",
    "PRAGMA",
    "ATTACH",
    "DETACH",
    "VACUUM",
    "TRUNCATE",
    "REINDEX",
    "LOAD_EXTENSION",
)

FORBIDDEN_IDENTIFIERS: tuple[str, ...] = (
    "invoices",
    "invoice_items",
    "invoice_taxes",
    "field_evidence",
    "extraction_runs",
    "sqlite_master",
    "sqlite_schema",
    "sqlite_temp_master",
    "raw_json",
)

_FENCE_RE = re.compile(r"^```[A-Za-z]*\s*\n?(.*?)\n?```$", re.DOTALL)
_KEYWORD_RE = re.compile(r"\b(" + "|".join(FORBIDDEN_KEYWORDS) + r")\b", re.IGNORECASE)
_IDENTIFIER_RE = re.compile(r"\b(" + "|".join(FORBIDDEN_IDENTIFIERS) + r")\b", re.IGNORECASE)
_RELATION_RE = re.compile(r"\b(?:FROM|JOIN)\s+([A-Za-z_]\w*)", re.IGNORECASE)
_CTE_RE = re.compile(
    r"(?:\bWITH(?:\s+RECURSIVE)?|,)\s*([A-Za-z_]\w*)\s*(?:\([^()]*\))?\s+AS\s*\(",
    re.IGNORECASE,
)


class SqlGuardError(ValueError):
    """Raised when generated SQL is not a single read-only query over the views."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(f"{code}: {message}")
        self.code = code


def clean_sql(raw: str) -> str:
    """Strip a Markdown code fence, surrounding whitespace and one trailing ``;``."""
    text = raw.strip()
    match = _FENCE_RE.match(text)
    if match:
        text = match.group(1).strip()
    if text.endswith(";"):
        text = text[:-1].rstrip()
    return text


def _mask(sql: str) -> str:
    """Blank string literals and comments; unquote double-quoted identifiers."""
    out: list[str] = []
    i = 0
    n = len(sql)
    while i < n:
        ch = sql[i]
        if ch == "'":
            j = i + 1
            while j < n:
                if sql[j] == "'":
                    if j + 1 < n and sql[j + 1] == "'":
                        j += 2
                        continue
                    break
                j += 1
            out.append(" " * (min(j, n - 1) - i + 1))
            i = j + 1
        elif sql.startswith("--", i):
            j = sql.find("\n", i)
            j = n if j == -1 else j
            out.append(" " * (j - i))
            i = j
        elif sql.startswith("/*", i):
            j = sql.find("*/", i + 2)
            j = n if j == -1 else j + 2
            out.append(" " * (j - i))
            i = j
        elif ch == '"':
            j = sql.find('"', i + 1)
            j = n if j == -1 else j
            out.append(sql[i + 1 : j])
            i = j + 1
        else:
            out.append(ch)
            i += 1
    return "".join(out)


def check_read_only(sql: str) -> tuple[str, ...]:
    """Return the allowed views referenced by ``sql`` or raise ``SqlGuardError``."""
    masked = _mask(sql).strip()
    if not masked:
        raise SqlGuardError("empty", "no SQL statement")
    if ";" in masked:
        raise SqlGuardError("multiple_statements", "only one statement is allowed")
    first = masked.split(None, 1)[0].upper()
    if first not in ("SELECT", "WITH"):
        raise SqlGuardError("not_select", f"statement starts with {first}")
    keyword = _KEYWORD_RE.search(masked)
    if keyword:
        raise SqlGuardError("forbidden_keyword", keyword.group(1).upper())
    identifier = _IDENTIFIER_RE.search(masked)
    if identifier:
        raise SqlGuardError("forbidden_relation", identifier.group(1))
    cte_names = {name.lower() for name in _CTE_RE.findall(masked)}
    views: set[str] = set()
    for name in _RELATION_RE.findall(masked):
        lowered = name.lower()
        if lowered in ALLOWED_VIEWS:
            views.add(lowered)
        elif lowered not in cte_names:
            raise SqlGuardError("forbidden_relation", name)
    return tuple(sorted(views))
